pub(super) fn read_artifact(path: &Path, limit: usize, label: &str) -> Result<Vec<u8>> {
    let metadata = fs::symlink_metadata(path)
        .with_context(|| format!("foreign-process {label} is unavailable"))?;
    if metadata.file_type().is_symlink() || !metadata.is_file() {
        bail!("foreign-process {label} must be a regular non-symlink file");
    }
    let mut file =
        File::open(path).with_context(|| format!("foreign-process {label} could not be opened"))?;
    let mut bytes = Vec::new();
    (&mut file)
        .take((limit + 1) as u64)
        .read_to_end(&mut bytes)
        .with_context(|| format!("foreign-process {label} could not be read"))?;
    if bytes.is_empty() || bytes.len() > limit {
        bail!("foreign-process {label} is empty or exceeds its byte limit");
    }
    Ok(bytes)
}

