export function selectVerifiedTextPreviewScalarRange(
  value: VerifiedTextContentPreviewView,
  requestedBytesHex: string,
  startScalarIndex: number,
  endScalarIndexInclusive: number,
): VerifiedTextPreviewScalarRangeSelection {
  verifyTextContentPreview(value, requestedBytesHex);
  const scalars = Array.from(value.previewText);
  if (!Number.isSafeInteger(startScalarIndex)
    || !Number.isSafeInteger(endScalarIndexInclusive)
    || startScalarIndex < 0
    || endScalarIndexInclusive < startScalarIndex
    || endScalarIndexInclusive >= scalars.length) {
    throw new Error('verified-text-preview-scalar-range-mismatch');
  }
  const outputText = scalars.slice(startScalarIndex, endScalarIndexInclusive + 1).join('');
  const outputUtf8ByteLength = new TextEncoder().encode(outputText).byteLength;
  if (outputText.length < 1 || outputUtf8ByteLength < 1
    || outputUtf8ByteLength > value.previewBytes) {
    throw new Error('verified-text-preview-scalar-range-mismatch');
  }
  return {
    startScalarIndex,
    endScalarIndexInclusive,
    scalarCount: endScalarIndexInclusive - startScalarIndex + 1,
    outputText,
    outputUtf8ByteLength,
    exactVerifiedPreviewText: true,
    sourceContentBeyondPreviewIncluded: false,
    canonicalPreviewEvidenceChanged: false,
    authorityGranted: false,
  };
}

